package com.agrolink.controller;import com.agrolink.dto.order.*;import com.agrolink.service.OrderService;import jakarta.validation.Valid;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/orders") public class OrderController{private final OrderService s;public OrderController(OrderService s){this.s=s;}@PostMapping("/checkout") public OrderResponse checkout(Authentication a,@Valid @RequestBody CheckoutRequest r){return s.checkout(a.getName(),r);}@PostMapping public OrderResponse place(Authentication a,@Valid @RequestBody DirectOrderRequest r){return s.place(a.getName(),r);}@GetMapping public List<OrderResponse> mine(Authentication a){return s.mine(a.getName());}@GetMapping("/seller") public List<OrderResponse> seller(Authentication a){return s.sellerOrders(a.getName());}@GetMapping("/{id}") public OrderResponse get(Authentication a,@PathVariable Long id){return s.get(a.getName(),id);}@PostMapping("/{id}/status") public OrderResponse updateStatus(Authentication a,@PathVariable Long id,@Valid @RequestBody UpdateOrderStatusRequest r){return s.updateStatus(a.getName(),id,r.status());}@PostMapping("/{id}/payment") public OrderResponse updatePayment(Authentication a,@PathVariable Long id,@Valid @RequestBody UpdateOrderPaymentRequest r){return s.updatePayment(a.getName(),id,r.status());}}